CREATE TABLE `wod_templates` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`owner_user_id` text,
	`wod_type` text NOT NULL,
	`time_cap_s` integer,
	`description` text,
	`body` text NOT NULL,
	`is_benchmark` integer DEFAULT false NOT NULL,
	`created_at` integer DEFAULT (unixepoch() * 1000) NOT NULL,
	`updated_at` integer DEFAULT (unixepoch() * 1000) NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX `wod_templates_global_name_uq` ON `wod_templates` (lower("name")) WHERE "wod_templates"."owner_user_id" is null;--> statement-breakpoint
CREATE UNIQUE INDEX `wod_templates_custom_name_uq` ON `wod_templates` (`owner_user_id`,lower("name")) WHERE "wod_templates"."owner_user_id" is not null;--> statement-breakpoint
CREATE INDEX `wod_templates_owner_idx` ON `wod_templates` (`owner_user_id`);--> statement-breakpoint
CREATE INDEX `wod_templates_type_idx` ON `wod_templates` (`wod_type`);--> statement-breakpoint
